\begin{figure}[ht]
\centering
\fig{ch01-universal}
\caption{Left: the universal property of the product. Every pair of arrows $f$, $g$ out of $X$ factors through one arrow $h=(f,g)$ into $A\times B$. Right: the naturality square of a
natural transformation $\eta\colon F\Rightarrow G$. Going right then down equals going down then right.}
\label{fig:universal}
\end{figure}

\begin{figure}[ht]
\centering
\fig{linear-ch10-wtensor}
\caption{The tensor $W$ as a cube of entries. Its front slice $A$ is a permutation matrix and its back slice $B$ has a single
$1$; since $A^{-1}B$ is a non-zero nilpotent matrix, $W$ has rank $3$, yet it is a limit of tensors of rank $2$.}
\label{linear:fig:wtensor}
\end{figure}

\begin{figure}[ht]
\centering
\fig{linear-ch10-omega}
\caption{Upper bounds for the exponent $\omega$ of matrix multiplication, from Strassen's $\log_27\approx2.807$ (1969) to $2.3713$
(2024). Since Coppersmith and Winograd (1990), all progress has come from the same ``laser method'', refined: $2.3755$, then
$2.3729$ (2012), $2.37286$ (2014), and, after three smaller steps, $2.37134$ (2024). These bounds are quoted, not proved here. The lower bound is still $\omega\ge2$.}
\label{linear:fig:omega}
\end{figure}

\begin{figure}[ht]
\centering
\fig{ch02-snake}
\caption{The snake lemma. The kernels of the vertical maps sit above the diagram, their cokernels below; the connecting homomorphism $\partial$ is the snake's body, running from the
top right to the bottom left. To compute $\partial(z)$: lift $z$ to $y\in B$, push it down to $b(y)\in B'$, which lies in $f'(A')$, pull it back to $x'\in A'$, and take its class.}
\label{fig:snake}
\end{figure}

\begin{figure}[ht]
\centering
\fig{ch03-varieties}
\caption{Left: the nodal cubic $y^2=x^3+x^2$ in $\R^2$. Its ideal is prime, so it is irreducible, although it crosses itself at the origin. Right: the zero set of $xz$ and $yz$ in $\R^3$, the union of the plane $z=0$ and
the $z$-axis, two irreducible components of different dimensions.}
\label{fig:varieties}
\end{figure}

\begin{figure}[ht]
\centering
\fig{ch04-speczx}
\caption{After Mumford: the spectrum of $\Z[x]$. The bottom line is $\operatorname{Spec}\Z$. Above each prime $p$ stands the fibre $\operatorname{Spec}\mathbb F_p[x]$, a vertical line made of the generic point $(p)$ and the
closed points $(p,f)$, one for each monic irreducible $\bar f$ modulo $p$, of which a few are drawn in grey. The curve is the closure of the point $(x^2+1)$: it meets the fibre at $p$ in two points
$(p,x\pm a)$ when $p\equiv1\pmod4$, in one point $(p,x^2+1)$ of degree $2$ when $p\equiv3\pmod4$, and has its two branches meeting at the single point $(2,x+1)$ of the fibre at $2$, where $x^2+1=(x+1)^2$.}
\label{fig:specz}
\end{figure}

\begin{figure}[ht]
\centering
\fig{ch05-cubicclass}
\caption{The real points of the cubic $E\colon y^2=x^3-x+1$. The line $y=1-2x$ meets $E$ at $P=(0,1)$, $Q=(1,-1)$ and $R=(3,-5)$, so the ideal it generates in $\C[x,y]/(y^2-x^3+x-1)$ is $\mathfrak m_P\mathfrak m_Q\mathfrak m_R$.
The vertical line $x=3$ gives $(x-3)=\mathfrak m_R\mathfrak m_{R'}$ with $R'=(3,5)$. In the class group, $[\mathfrak m_P][\mathfrak m_Q]=[\mathfrak m_{R'}]$: the chord-and-tangent addition of points.}
\label{fig:cubicclass}
\end{figure}

\begin{figure}[ht]
\centering
\fig{ch06-surfaces}
\caption{The torus, the Klein bottle and the projective plane, as polygons with edges glued according to the arrows. Each has a cell structure with one $2$-cell, and the boundary of the $2$-cell gives $d_2$:
$a+b-a-b=0$, $a+b-a+b=2b$ and $a+a=2a$.}
\label{fig:surfaces}
\end{figure}

\begin{figure}[ht]
\centering
\fig{ch07-circle}
\caption{Rational points on the unit circle, from Hilbert's Theorem~90 for $\Q(i)/\Q$: each point $\frac{(m+ni)^2}{m^2+n^2}$ with $1\le m,n\le7$ coprime is drawn, with the line from $(-1,0)$ of slope $\frac nm$ that finds it.}
\label{fig:rationalcircle}
\end{figure}

\begin{figure}[ht]
\centering
\fig{ch08-wedderburn}
\caption{Wedderburn's theorem for $\mathfrak S_4$: under the isomorphism of Corollary~\ref{cor:wedderburnCG}, an element of $\C[\mathfrak S_4]$ is a block-diagonal matrix with one block for each irreducible character (Volume~3, Example~11.13), and the
$24$ coordinates of $\C[\mathfrak S_4]$ become the $1+1+4+9+9$ free entries of the blocks.}
\label{fig:wedderburn}
\end{figure}

\begin{figure}[ht]
\centering
\fig{ch09-hooks}
\caption{Left: the diagram of $\lambda=(5,4,2,1)$ with the hook length in each cell; the hook of the cell $(1,2)$ is shaded, of length $6$. By the hook length formula $f^\lambda=12!/(8\cdot6\cdot4\cdot3\cdot1\cdot6\cdot4\cdot2\cdot1\cdot3\cdot1\cdot1)=5775$.
Right: one run of the hook walk of Theorem~\ref{thm:hook}, from $(1,1)$ to $(3,1)$ (down its leg), then to the corner $(3,2)$ (along its arm). The four corners are marked with dots.}
\label{fig:hooks}
\end{figure}

\begin{figure}[ht]
\centering
\fig{ch11-weights}
\caption{Weight diagrams of two representations of $U(3)$, drawn in the plane $\mu_1+\mu_2+\mu_3=\text{constant}$. Left: $V_{(2,1,0)}$, of dimension $8$: the six permutations of $(2,1,0)$, and the weight $(1,1,1)$ with multiplicity $2$ (the circled centre); restricted to $SU(3)$,
this is Gell-Mann's ``eightfold way'' of 1961, in which the eight lightest baryons fill the weights. Right: $V_{(3,0,0)}=\operatorname{Sym}^3\C^3$, of dimension $10$, whose tenth weight, at a corner of the triangle, was a particle not yet observed; Gell-Mann
predicted it in 1962, and the $\Omega^-$ was found at Brookhaven in 1964.}
\label{fig:weights}
\end{figure}
